SharedLock lk(partition_map_mx_);

if (partition_to_bucket_.empty()) {
    LOG(WARNING) << "FindBucket called on an empty View";
    return nullptr;
}

if (hash < 0.0f || hash > 1.0f) {
    LOG(FATAL) << "Hash value out of range [0,1]: " << hash;
}

auto it = partition_to_bucket_.upper_bound(hash);
if (it == partition_to_bucket_.end()) {
    it = partition_to_bucket_.begin();  // wrap around the ring
}
return it->second;

